  function isValidState(value) {
    const collections = ["teams","users","roles","categories","ratingScales","templates","competencies","frameworks","assessments","initialRequests","reassessmentRequests","idps","careerTransitions","notifications","audit"];
    return value && value.schemaVersion === 5 && collections.every(key=>Array.isArray(value[key])) && value.demo;
  }
  function readWindowState() {
    try {
      if (!window.name.startsWith(WINDOW_STATE_PREFIX)) return null;
      return JSON.parse(window.name.slice(WINDOW_STATE_PREFIX.length));
    } catch (error) { return null; }
  }
  function persistState(value) {
    const serialized=JSON.stringify(value);
    try { localStorage.setItem(STORAGE_KEY,serialized); } catch (error) { console.warn("EnPath localStorage unavailable; using same-tab fallback",error); }
    try { window.name=`${WINDOW_STATE_PREFIX}${serialized}`; } catch (error) { console.warn("EnPath same-tab fallback unavailable",error); }
  }
  function clearPersistedState() {
    try { localStorage.removeItem(STORAGE_KEY); } catch (error) { console.warn("EnPath localStorage reset unavailable",error); }
    if (window.name.startsWith(WINDOW_STATE_PREFIX)) window.name="";
  }
  function loadState() {
    let stored=null;
    try {
      stored = JSON.parse(localStorage.getItem(STORAGE_KEY));
    } catch (error) { console.warn("EnPath demo state was reset", error); }
    const fallback=readWindowState();
    const candidate=location.protocol==="file:"&&isValidState(fallback)?fallback:isValidState(stored)?stored:isValidState(fallback)?fallback:null;
    if(candidate){persistState(candidate);return candidate;}
    const fresh = seedData();
    persistState(fresh);
    return fresh;
  }
