  function esc(value) { return String(value == null ? "" : value).replace(/[&<>'"]/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"}[c])); }
  function slug(value) { return String(value || "").toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,""); }
  function badge(status) { return `<span class="badge ${slug(status)}">${esc(status)}</span>`; }
  function initials(name) { return String(name).split(" ").map(p=>p[0]).slice(-2).join(""); }
