  function myIdpView() {
    const plans=state.idps.filter(i=>i.employeeId==="minh"),idp=plans.find(i=>i.status==="Active")||plans[0];
    return pageHead("Your development system","My IDP","Turn gaps into plans, move actions through delivery and attach evidence that can support a future re-assessment.",`<button class="button" data-action="create-idp">Create IDP</button><button class="button primary" data-action="add-idp-action" data-idp="${idp.id}">Add action</button>`,`<span class="chip">${plans.filter(plan=>plan.status==="Active").length} Active</span><span class="chip">Target · ${esc(idp.target)}</span>${badge(idp.status)}`)+
      `<section class="card" style="margin-bottom:16px"><div class="section-head" style="padding:18px 18px 0"><div><h2>My development plans</h2><p>Draft, Active, Completed and Archived plans remain visible.</p></div></div>${plans.map(plan=>`<div class="list-card"><span><b>${esc(plan.title)}</b><span class="meta" style="display:block">${esc(plan.competency)} · target ${esc(plan.targetDate)}</span></span><div class="actions">${badge(plan.status)}${plan.status==="Draft"?`<button class="button small primary" data-action="idp-status" data-idp="${plan.id}" data-status="Active">Activate</button>`:""}${plan.status==="Active"?`<button class="button small" data-action="idp-status" data-idp="${plan.id}" data-status="Completed">Complete</button>`:""}${plan.status==="Completed"?`<button class="button small danger" data-action="idp-status" data-idp="${plan.id}" data-status="Archived">Archive</button>`:""}</div></div>`).join("")}</section><section class="card pad feature" style="margin-bottom:16px"><div class="section-head"><div><div class="eyebrow">${idp.status==="Active"?"Active plan":"Selected plan"}</div><h2>${esc(idp.title)}</h2><p>${esc(idp.competency)} · Owner ${esc(idp.owner)} · Target ${esc(idp.targetDate)}</p></div><strong style="font-family:var(--font-display);font-size:34px">${idp.progress}%</strong></div><div class="progress"><span style="width:${idp.progress}%"></span></div></section>
      <div class="kanban">${["Not Started","In Progress","Blocked","Done"].map(status=>`<section class="kanban-col" data-status="${status}"><div class="kanban-head"><span>${status}</span><span class="badge">${idp.actions.filter(a=>a.status===status).length}</span></div>${idp.actions.filter(a=>a.status===status).map(a=>`<article class="action-card ${a.deadline<today()&&a.status!=="Done"?"overdue":""}" draggable="true" data-action-id="${a.id}" data-action="idp-action-detail"><div class="eyebrow">${esc(a.type)}</div><h3>${esc(a.title)}</h3><p class="meta">${esc(a.competency)} · due ${esc(a.deadline)}</p><div class="cluster">${badge(a.status)}<span class="chip">${a.evidence.length} evidence</span></div></article>`).join("")}</section>`).join("")}</div>
      <div class="grid two" style="margin-top:16px"><section class="card pad"><div class="section-head"><div><h2>Activity timeline</h2><p>Manager comments and suggested updates.</p></div></div>${timeline(idp.activity)}</section><section class="card pad"><h2>Evidence ready for re-assessment</h2><div class="evidence-list">${idp.actions.flatMap(a=>a.evidence.map(e=>`<div class="evidence"><b>${esc(e.type)}</b> · ${esc(e.value)}<br><span class="meta">${esc(a.title)}</span></div>`)).join("")}</div><button class="button" data-action="create-reassessment">Link to re-assessment request</button></section></div>`;
  }

