  function captureTemplateStep() {
    const form=document.getElementById("template-form");if(!form)return true;
    const data=new FormData(form);
    if(templateStep===1){const name=String(data.get("name")||"").trim();if(!name){toast("Template name is required","Add a clear reusable template name before continuing.");return false;}Object.assign(templateDraft,{name,scale:data.get("scale"),purpose:data.get("purpose")||""});}
    if(templateStep===2){const categories=data.getAll("categories");if(!categories.length){toast("Choose at least one category","Templates must allow at least one HR-governed competency category.");return false;}templateDraft.categories=categories;}
    if(templateStep===3)templateDraft.defaults=data.getAll("defaults");
    return true;
  }
  function templateModal() {
    const steps=["Basics","Categories","Default competencies","Review"];
    const activeScale=state.ratingScales.find(s=>s.status==="Active")||state.ratingScales[0];
    if(!templateDraft)templateDraft={name:"Engineering Growth Starter",scale:activeScale.version,purpose:"Fast setup for software engineering team frameworks.",categories:["Technical","Soft Skills","Product / Business"],defaults:["Technical Communication","Cross-team Collaboration"]};
    modal("Create framework template",`<div class="stepper">${steps.map((s,i)=>`<div class="step ${i+1===templateStep?"active":i+1<templateStep?"done":""}">${i+1}. ${s}</div>`).join("")}</div><form id="template-form" data-form="template">${templateStep===1?`<div class="form-grid"><div class="field"><label>Template name</label><input name="name" required value="${esc(templateDraft.name)}"></div><div class="field"><label>Rating scale</label><select name="scale">${state.ratingScales.filter(s=>s.status==="Active").map(s=>`<option value="${esc(s.version)}" ${s.version===templateDraft.scale?"selected":""}>v${esc(s.version)} · Active</option>`).join("")}</select></div><div class="field full"><label>Purpose</label><textarea name="purpose">${esc(templateDraft.purpose)}</textarea></div></div>`:templateStep===2?`<div class="stack">${state.categories.filter(c=>c.status==="Active").map(c=>`<label class="list-card"><span><b>${esc(c.name)}</b><span class="meta" style="display:block">${esc(c.rule)}</span></span><input type="checkbox" name="categories" value="${esc(c.name)}" ${templateDraft.categories.includes(c.name)?"checked":""}></label>`).join("")}</div>`:templateStep===3?`<div class="stack">${state.competencies.map(c=>`<label class="list-card"><span><b>${esc(c.name)}</b><span class="meta" style="display:block">Optional default · ${esc(c.category)}</span></span><input type="checkbox" name="defaults" value="${esc(c.name)}" ${templateDraft.defaults.includes(c.name)?"checked":""}></label>`).join("")}</div>`:`<div class="validation success"><b>Ready to create</b><p>${esc(templateDraft.name)} · rating scale v${esc(templateDraft.scale)} · ${esc(templateDraft.categories.join(", ")||"No categories selected")} · ${templateDraft.defaults.length} default competencies.</p></div>`}</form>`,`<button class="button" data-action="template-prev" ${templateStep===1?"disabled":""}>Back</button>${templateStep<4?`<button class="button primary" data-action="template-next">Continue</button>`:`<button class="button" data-action="save-template-draft">Save Draft</button><button class="button primary" data-action="activate-template">Create Active template</button>`}`,true);
  }
