    drawer(`${request.employee} · ${request.competencies.join(", ")}`,`${badge(request.status)}<p style="margin-top:12px">${esc(request.reason)}</p><div class="divider"></div><div class="metric-line"><span>Linked plan</span><b>${esc(idp?.title||"—")}</b></div><div class="metric-line"><span>Linked actions</span><b>${request.actionIds.length}</b></div><div class="metric-line"><span>Preferred timing</span><b>${esc(request.timing)}</b></div><h3 style="margin-top:18px">Evidence</h3><div class="evidence-list">${request.evidence.length?request.evidence.map(e=>`<div class="evidence">${esc(e)}</div>`).join(""):`<p class="muted">No evidence attached.</p>`}</div><div class="divider"></div><h3>Status timeline</h3>${timeline(request.timeline)}<div class="divider"></div><div class="actions"><button class="button primary" data-action="accept-request" data-request="${request.id}" ${canDecide?"":"disabled"}>Accept</button><button class="button" data-action="more-evidence" data-request="${request.id}" ${canDecide?"":"disabled"}>Request more evidence</button><button class="button danger" data-action="decline-request" data-request="${request.id}" ${canDecide?"":"disabled"}>Decline</button>${request.assessmentId?`<button class="button attention" data-action="open-linked-assessment" data-assessment="${request.assessmentId}">${request.status==="Completed"?"View assessment":"Continue assessment"}</button>`:""}</div>`);
