  function exportAudit() {
    const cutoff=new Date();cutoff.setDate(cutoff.getDate()-30);
    const rows=state.audit.filter(a=>(auditFilters.object==="All governed objects"||a.object===auditFilters.object||(auditFilters.object==="Role / Level"&&a.object==="Role"))&&(auditFilters.actor==="All actors"||a.actor===auditFilters.actor)&&(auditFilters.range==="All history"||new Date(a.date.replace(" ","T"))>=cutoff));
    const csv=[["Timestamp","Object","Action","Actor","Impacted","Before","After"],...rows.map(a=>[a.date,a.object,a.action,a.actor,a.impacted,a.before,a.after])].map(row=>row.map(value=>`"${String(value??"").replace(/"/g,'""')}"`).join(",")).join("\n");
    try{const url=URL.createObjectURL(new Blob([csv],{type:"text/csv"})),link=document.createElement("a");link.href=url;link.download="enpath-audit-visible.csv";link.click();URL.revokeObjectURL(url);toast("Audit CSV downloaded",`${rows.length} visible events exported.`);}catch(error){toast("Audit export unavailable","Your browser blocked the local download. The filtered timeline remains visible.");}
  }
