  function bindDragAndDrop() {
    document.querySelectorAll(".action-card[draggable=true]").forEach(card=>card.addEventListener("dragstart",e=>e.dataTransfer.setData("text/plain",card.dataset.actionId)));
    document.querySelectorAll(".kanban-col").forEach(col=>{
      col.addEventListener("dragover",e=>e.preventDefault());
      col.addEventListener("drop",e=>{e.preventDefault();const id=e.dataTransfer.getData("text/plain"),action=state.idps.flatMap(i=>i.actions).find(a=>a.id===id);if(action){action.status=col.dataset.status;updateIdpProgress();saveState(`Action moved to ${action.status}`);render();}});
    });
  }
  function updateIdpProgress() {
    state.idps.forEach(idp=>{const weights={"Not Started":0,"In Progress":50,"Blocked":25,"Done":100};idp.progress=Math.round(idp.actions.reduce((sum,a)=>sum+weights[a.status],0)/Math.max(idp.actions.length,1));});
  }

