  function jumpState(value) {
    if (!value) return;
    if (value==="profile-empty") { state.demo.employeeState="empty"; route="profile"; }
    else if (value==="profile") { state.demo.employeeState="completed"; route="profile"; }
    else if (value==="ready-framework") { fixDemoFramework(false); state.demo.managerFramework="ready"; route="team-framework"; }
    else { route=value; }
    location.hash=route;saveState();render();
  }
