  function completeAssessment() {const a=state.assessments.find(x=>x.id===selected.assessmentWorkspace);if(!a||a.status!=="Active"||!a.scores.every(s=>s.manager))return;const recommendation=document.getElementById("assessment-summary")?.value||a.summary?.recommendation||"Continue building evidence through the linked development plan.";a.status="Completed";a.completed=today();a.summary={strengths:a.scores.filter(s=>s.manager>=s.expected).map(s=>s.competency).slice(0,3).join(", ")||"Progress across assessed scope.",gaps:a.scores.filter(s=>s.manager<s.expected).map(s=>s.competency).join(", ")||"No confirmed gap in this scope.",recommendation};const user=state.users.find(u=>u.id===a.employeeId);user.lastAssessment=today();if(a.employeeId==="minh")state.demo.employeeState="completed";const request=state.reassessmentRequests.find(r=>r.assessmentId===a.id);if(request)addTimeline(request,"Completed","Luc Tran","Focused assessment completed and linked to assessment history.");notify(a.employeeId,"Assessment completed",`${a.cycle} completed`,`Your score summary, competency gap and historical snapshot are now available.`,`my-assessments`);logAudit("Assessment",`${a.employee} assessment completed`,"Luc Tran",`${a.framework} and scale v${a.scale} snapshot locked`,"Active","Completed");selected.assessmentWorkspace=null;saveState(`Assessment completed for ${a.employee}`);render();}
  function showCompletedAssessment(a) {drawer(`${a.employee} · ${a.cycle}`,`${badge(a.status)}<p style="margin-top:12px">Snapshot: ${esc(a.framework)} · rating scale v${esc(a.scale)}</p><div class="divider"></div>${a.status==="Cancelled"?`<div class="validation warning"><b>Assessment cancelled</b><p>Partial scores are not treated as a completed competency profile. Historical completed assessments remain unchanged.</p></div>`:a.scores.length?radarChart(a.scores,[{label:"Self",className:"radar-self",color:"var(--amber)",value:r=>r.self},{label:"Manager",className:"radar-manager",color:"var(--teal)",value:r=>r.manager},{label:"Expected",className:"radar-target",color:"var(--blue)",value:r=>r.expected}]):`<p class="muted">Summary-only demo record.</p>`}${a.status==="Completed"?`<div class="validation success"><b>Strengths</b><p>${esc(a.summary.strengths)}</p></div><div class="validation" style="margin-top:8px"><b>Gaps</b><p>${esc(a.summary.gaps)}</p></div>`:""}`);}
  function submitAcceptRequest(v) {const r=state.reassessmentRequests.find(x=>x.id===v.requestId),fw=publishedFramework(),user=currentEmployee();if(!r||r.status!=="Submitted"){toast("Request is no longer actionable","Only Submitted requests can start a focused assessment.");return;}if(state.assessments.some(a=>a.employeeId===r.employeeId&&a.status==="Active")){toast("Assessment already active","Complete or cancel the current active assessment before accepting another request.");return;}const scope=r.competencies.map(name=>frameworkCompetencyByName(fw,name)?.id).filter(Boolean);if(scope.length!==r.competencies.length){toast("Framework scope changed","One or more requested competencies are not in the current Published framework. Update the request scope first.");return;}const assessment={id:uid("asmt"),employeeId:"minh",employee:"Minh Nguyen",manager:"Luc Tran",cycle:"Focused re-assessment · August 2026",frameworkId:fw.id,framework:`${fw.name} v${fw.version}`,scale:fw.scale,status:"Active",deadline:v.deadline,completed:null,selfOptional:Boolean(v.selfOptional),scores:scope.map(id=>{const c=compById(id);return{competencyId:id,competency:c.name,category:c.category,self:null,manager:null,expected:c.expected[user.level]||3,target:c.expected[user.level]||3,evidence:r.evidence.join(" · "),comment:""};}),summary:{strengths:"",gaps:"",recommendation:""}};state.assessments.push(assessment);r.assessmentId=assessment.id;addTimeline(r,"Accepted","Luc Tran","Accepted and started a focused assessment using the current published framework.");notify("minh","Request accepted","Focused re-assessment started",`Deadline ${v.deadline}. Self-assessment is optional.`,"my-requests");overlay=null;selected.assessmentWorkspace=assessment.id;saveState("Request accepted and focused assessment started");navigate("assessments");}
  function acceptInitialRequest(id) {const r=state.initialRequests.find(x=>x.id===id);if(!r||r.status!=="Submitted")return;overlay=null;startAssessmentModal(r.employeeId,r.id);}
  function declineRequest(id) {const r=state.reassessmentRequests.find(x=>x.id===id);if(!r||r.status!=="Submitted")return;addTimeline(r,"Declined","Luc Tran","Declined because the evidence does not yet demonstrate sustained behavior.");notify("minh","Request declined","Re-assessment request declined","Luc included a reason in the request timeline.","my-requests");overlay=null;saveState("Re-assessment request declined");render();}
  function completeRequest(id) {const r=state.reassessmentRequests.find(x=>x.id===id);addTimeline(r,"Completed","Luc Tran","Focused assessment completed and linked to assessment history.");notify("minh","Re-assessment completed","Distributed Systems score updated","The focused assessment is available in your history.","my-assessments");overlay=null;saveState("Re-assessment request completed");render();}
  function submitMoreEvidence(v) {const r=state.reassessmentRequests.find(x=>x.id===v.requestId);if(!r||r.status!=="Submitted")return;r.managerMessage=v.message;addTimeline(r,"More Evidence Needed","Luc Tran",v.message);notify("minh","Request update","More evidence needed",v.message,"my-requests");overlay=null;saveState("Evidence request sent to Minh");render();}
  function submitRequestEvidence(v,form) {const r=state.reassessmentRequests.find(x=>x.id===v.requestId),file=form.querySelector("input[type=file]")?.files[0];r.evidence.push(v.message);if(file)r.evidence.push(file.name);addTimeline(r,"Submitted","Minh Nguyen","Added requested evidence and resubmitted.");notify("luc","Request update","Minh added evidence",v.message,"assessment-requests");overlay=null;saveState("Evidence added and request resubmitted");render();}
  function cancelAssessment(id){const a=state.assessments.find(x=>x.id===id);if(!a||a.status!=="Active")return;a.status="Cancelled";a.completed=today();const user=state.users.find(u=>u.id===a.employeeId),previous=state.assessments.filter(item=>item.employeeId===a.employeeId&&item.status==="Completed").sort((x,y)=>String(y.completed).localeCompare(String(x.completed)))[0];if(user)user.lastAssessment=previous?.completed||"Never";const reassessment=state.reassessmentRequests.find(r=>r.assessmentId===a.id);if(reassessment)addTimeline(reassessment,"Cancelled","Luc Tran","The linked focused assessment was cancelled.");const initial=state.initialRequests.find(r=>r.assessmentId===a.id);if(initial){initial.status="Cancelled";initial.timeline.push({status:"Cancelled",date:today(),actor:"Luc Tran",note:"The linked assessment was cancelled."});}notify(a.employeeId,"Assessment cancelled",`${a.cycle} cancelled`,`Luc cancelled the active assessment. Historical completed assessments are unchanged.`,`my-assessments`);logAudit("Assessment",`${a.employee} assessment cancelled`,"Luc Tran",a.framework,"Active","Cancelled");overlay=null;selected.assessmentWorkspace=null;saveState("Assessment cancelled");render();}
  function openLinkedAssessment(id){const assessment=state.assessments.find(a=>a.id===id);if(!assessment)return;if(["Completed","Cancelled"].includes(assessment.status)){showCompletedAssessment(assessment);return;}overlay=null;selected.assessmentWorkspace=id;navigate("assessments");}
  function cancelReassessment(id){const request=state.reassessmentRequests.find(r=>r.id===id);if(!request||!["Draft","Submitted"].includes(request.status))return;const before=request.status;addTimeline(request,"Cancelled","Minh Nguyen","Cancelled the request before a Manager decision.");if(before==="Submitted")notify("luc","Request cancelled","Minh cancelled a re-assessment request",request.competencies.join(", "),"assessment-requests");overlay=null;saveState("Re-assessment request cancelled");render();}
  function submitInitialRequest(v) {if(state.initialRequests.some(r=>r.employeeId==="minh"&&["Submitted","Accepted"].includes(r.status))){toast("Request already in progress","Track the existing request or assessment before submitting another.");return;}state.initialRequests.push({id:uid("initial"),employeeId:"minh",employee:"Minh Nguyen",reason:v.reason,note:v.note,timing:v.timing,status:"Submitted",timeline:[{status:"Submitted",date:today(),actor:"Minh Nguyen",note:v.note}]});notify("luc","Assessment request","Minh requested an initial assessment",`${v.reason} · ${v.timing}`,"assessments");overlay=null;saveState("Initial assessment request submitted");render();}
  function submitSelfAssessment(form,data) {const a=state.assessments.find(x=>x.id===data.get("assessmentId"));if(!a||a.status!=="Active")return;a.scores.forEach((s,index)=>{const raw=data.get(`score-${index}`);s.self=raw===""?null:Number(raw);const evidence=data.get(`evidence-${index}`);if(evidence)s.evidence=evidence;});notify("luc","Self-assessment","Minh added optional self-assessment input",`${a.cycle} now includes employee reference scores.`,"assessments");overlay=null;saveState("Optional self-assessment saved");render();}
  function submitReassessment(form,data,status) {const competencies=data.getAll("competencies"),evidence=data.getAll("evidence"),v=Object.fromEntries(data.entries()),reason=String(v.reason||"").trim();if(status==="Submitted"&&!competencies.length){toast("Choose at least one competency","The request remains open so you can correct it.");return;}if(status==="Submitted"&&!reason){toast("Add an improvement reason","Explain what changed before submitting the request.");return;}if(status==="Submitted"&&!evidence.length){toast("Attach at least one evidence item","Submitted re-assessment requests must link meaningful development evidence.");return;}let r=state.reassessmentRequests.find(item=>item.id===v.requestId);const isNew=!r;if(!r){r={id:uid("req"),employeeId:"minh",employee:"Minh Nguyen",managerMessage:"",timeline:[]};state.reassessmentRequests.unshift(r);}Object.assign(r,{competencies,reason,idpId:v.idpId,actionIds:v.actionId?[v.actionId]:[],evidence,timing:v.timing,status});r.timeline.push({status,date:today(),actor:"Minh Nguyen",note:status==="Draft"?isNew?"Saved a private request draft.":"Updated the private request draft.":"Submitted evidence-linked re-assessment request."});if(status==="Submitted")notify("luc","Request","Minh requested re-assessment",competencies.join(", "),"assessment-requests");overlay=null;saveState(`Re-assessment request ${status.toLowerCase()}`);render();}
  function saveReassessment(status) {const form=document.getElementById("reassessment-form"),data=new FormData(form);submitReassessment(form,data,status);}
  function submitIdp(v) {state.idps.push({id:uid("idp"),employeeId:"minh",employee:"Minh Nguyen",title:v.title,competency:v.competency,target:v.target,targetDate:v.targetDate,owner:v.owner,status:"Draft",progress:0,actions:[],activity:[{date:today(),actor:"Minh Nguyen",text:"Created the development plan."}]});overlay=null;saveState("Development plan created");render();}
  function submitManagerIdp(v) {const user=state.users.find(u=>u.id===v.employeeId);state.idps.push({id:uid("idp"),employeeId:user.id,employee:user.name,title:v.title,competency:v.competency,target:"",targetDate:v.targetDate,owner:v.owner==="Employee"?user.name:"Luc Tran",status:"Draft",progress:0,actions:[],activity:[{date:today(),actor:"Luc Tran",text:"Created a draft development plan with the employee."}]});notify(user.id,"Development plan",`Luc created a Draft IDP`,v.title,"my-idp");overlay=null;saveState(`Draft IDP created for ${user.name}`);render();}
  function submitAction(v,form) {const idp=state.idps.find(i=>i.employeeId==="minh"&&i.status==="Active")||state.idps.find(i=>i.employeeId==="minh"),existing=idp.actions.find(a=>a.id===v.id),file=form.querySelector("input[type=file]")?.files[0],evidence=existing?existing.evidence.filter(item=>item.type==="File").map(item=>({...item})):[];if(v.textEvidence)evidence.push({type:"Text",value:v.textEvidence});if(v.linkEvidence)evidence.push({type:"Link",value:v.linkEvidence});if(file&&!evidence.some(item=>item.type==="File"&&item.value===file.name))evidence.push({type:"File",value:file.name});const action={id:existing?.id||uid("act"),title:v.title,type:v.type,competency:v.competency,deadline:v.deadline,status:v.status,evidence};if(existing)Object.assign(existing,action);else idp.actions.push(action);idp.activity.unshift({date:today(),actor:"Minh Nguyen",text:`${existing?"Updated":"Added"} action: ${v.title}.`});updateIdpProgress();overlay=null;saveState("Development action saved with evidence");render();}
  function changeIdpStatus(id,status){if(status==="Archived"){confirmAction("Archive development plan","Archive this completed plan? Its actions, evidence and activity timeline remain available.",`confirm-archive-idp:${id}`,"Archive plan");return;}applyIdpStatus(id,status);}
  function applyIdpStatus(id,status){const idp=state.idps.find(i=>i.id===id);if(!idp)return;const before=idp.status;idp.status=status;idp.activity.unshift({date:today(),actor:"Minh Nguyen",text:`Changed plan status from ${before} to ${status}.`});overlay=null;saveState(`Development plan is now ${status}`);render();}
  function submitCheckin(v) {const idp=state.idps.find(i=>i.id===v.idpId);idp.activity.unshift({date:today(),actor:"Luc Tran",text:`Check-in scheduled for ${v.date}: ${v.agenda}`});notify("minh","IDP check-in","Luc scheduled a development check-in",`${v.date} · ${v.agenda}`,"my-idp");overlay=null;saveState("Development check-in scheduled");render();}
  function submitComment(v) {const idp=state.idps.find(i=>i.id===v.idpId);idp.activity.unshift({date:today(),actor:"Luc Tran",text:v.comment});notify("minh","IDP comment","Luc commented on your development plan",v.comment,"my-idp");overlay=null;saveState("Comment added to development plan");render();}
  function openNotification(id) {const n=state.notifications.find(x=>x.id===id);n.read=true;saveState();navigate(n.route);}
  function showCompletedInitialTracker() {drawer("Initial assessment request",`<div class="timeline"><div class="timeline-item"><b>Submitted</b><span class="meta">${today()} · Minh Nguyen</span><p>Your request is visible to Luc.</p></div><div class="timeline-item"><b>Manager action next</b><p>Luc can accept the request or start an assessment directly.</p></div></div>`);}
  function requestMemberEvidence(userId) {const user=state.users.find(u=>u.id===userId);notify(userId,"Evidence request","Luc requested new competency evidence","Add a work example or link it to an IDP action before the next check-in.",userId==="minh"?"my-idp":"profile");saveState(`Evidence request sent to ${user.name}`);render();}

  document.addEventListener("keydown",event=>{if(event.key==="Escape"&&overlay){overlay=null;render();}});
  document.addEventListener("click",event=>{if(document.body.classList.contains("nav-open")&&!event.target.closest?.(".sidebar")&&!event.target.closest?.('[data-action="toggle-nav"]'))document.body.classList.remove("nav-open");});
  window.addEventListener("hashchange",()=>{const next=location.hash.replace("#","");if(next&&next!==route){route=next;overlay=null;render();}});
